definitions.append(StructureDefinition(
    className='CSolverTimer',
    addDictionaryAccess=False,
    appendToFile=False,
    classDescription=r'Structure for timing in solver. Each Real variable is used to measure the CPU time which certain parts of the solver need. This structure is only active if the code is not compiled with the __FAST_EXUDYN_LINALG option and if displayComputationTime is set True. Timings will only be filled, if useTimer is True.',
    latexText=r"""
%++++++++++++++++++++++++++++++++++++++
\mysubsectionlabel{Solver substructures}{sec:solverSubstructures}
This section includes structures contained in the solver, which can be accessed via the Python interface during solution or for building a customized solver in Python.
There is plenty of possibilities to interact with the solvers, being it the extraction of data at the end (such as .it or .conv), computation of mass matrix or system matrices, and finally the modification of solver structures (which may have effect or not). In any case, there is no full description for all these methods and the user must always consider the according C++ function to verify the desired behavior.
""",
    writePybindIncludes=True,
    members=[
        StructureParameter(type=Tbool, cFlags=SFPybind,
            pythonName='useTimer',
            defaultValue=True,
            description=r'flag to decide, whether the timer is used (true) or not'),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='total',
            defaultValue=0.,
            description=r'total time measured between start and end of computation (static/dynamics)'),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='factorization',
            defaultValue=0.,
            description=r'solve or inverse'),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='newtonIncrement',
            defaultValue=0.,
            description=r'Jac$^{-1}$ * RHS; backsubstitution'),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='integrationFormula',
            defaultValue=0.,
            description=r'time spent for evaluation of integration formulas'),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='ODE2RHS',
            defaultValue=0.,
            description=r'time for residual evaluation of \hac{ODE2} right-hand-side'),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='ODE1RHS',
            defaultValue=0.,
            description=r'time for residual evaluation of \hac{ODE1} right-hand-side'),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='AERHS',
            defaultValue=0.,
            description=r'time for residual evaluation of algebraic equations right-hand-side'),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='totalJacobian',
            defaultValue=0.,
            description=r'time for all jacobian computations'),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='jacobianODE1',
            defaultValue=0.,
            description=r"""jacobian w.r.t. coordinates of \hac{ODE1} equations (not counted in sum)"""),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='jacobianODE2',
            defaultValue=0.,
            description=r"""jacobian w.r.t. coordinates of \hac{ODE2} equations (not counted in sum)"""),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='jacobianODE2_t',
            defaultValue=0.,
            description=r"""jacobian w.r.t. coordinates_t of \hac{ODE2} equations (not counted in sum)"""),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='jacobianAE',
            defaultValue=0.,
            description=r'jacobian of algebraic equations (not counted in sum)'),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='massMatrix',
            defaultValue=0.,
            description=r'mass matrix computation'),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='reactionForces',
            defaultValue=0.,
            description=r'CqT * lambda'),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='postNewton',
            defaultValue=0.,
            description=r'discontinuous iteration / PostNewtonStep'),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='errorEstimator',
            defaultValue=0.,
            description=r'for explicit solvers, additional evaluation'),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='writeSolution',
            defaultValue=0.,
            description=r'time for writing solution'),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='overhead',
            defaultValue=0.,
            description=r'overhead, such as initialization, copying and some matrix-vector multiplication'),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='realtimeIdleCPU',
            defaultValue=0.,
            description=r'time waited for next frame to compute and draw if simulateInRealtime is True'),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='python',
            defaultValue=0.,
            description=r'time spent for Python functions'),
        StructureParameter(type=TReal, cFlags=SFPybind,
            pythonName='visualization',
            defaultValue=0.,
            description=r'time spent for visualization in computation thread'),
        StructureFunction(type=Tvoid, cFlags=SFPybind,
            pythonName='Reset',
            args='bool useSolverTimer',
            implementation='*this = CSolverTimer(); useTimer = useSolverTimer;',
            description=r'reset solver timings to initial state by assigning default values; useSolverTimer sets the useTimer flag'),
        StructureFunction(type=TReal, cFlags=SFConst+SFNoDictType+SFPybind+SFReturnCopy,
            pythonName='Sum',
            description=r'compute sum of all timers (except for those counted multiple, e.g., jacobians'),
        StructureFunction(type=Tvoid, cFlags=SFPybind,
            pythonName='StartTimer',
            args='Real& value',
            implementation='if (useTimer) { value -= EXUstd::GetTimeInSeconds();}',
            description=r'start timer function for a given variable; subtracts current CPU time from value'),
        StructureFunction(type=Tvoid, cFlags=SFPybind,
            pythonName='StopTimer',
            args='Real& value',
            implementation='if (useTimer) { value += EXUstd::GetTimeInSeconds();}',
            description=r'stop timer function for a given variable; adds current CPU time to value'),
        StructureFunction(type=TString, cFlags=SFConst+SFNoDictType+SFPybind+SFReturnCopy,
            pythonName='ToString',
            description=r'converts the current timings to a string'),
        ],
    ))

